\label{defi1}Let $M$ be an $n$-dimensional manifold. A function $F:TM\longrightarrow [0,\infty)$ is a \textit{Finslerian metric} 
   	on $M$ if :
   	\begin{itemize}
   		\item [(i)] $F$ is $C^{\infty}$ on the entire slit tangent bundle $\mathring{T}M$,
   		\item [(ii)] $F$ is positively $1$-homogeneous on the fibers of $TM$, that is \\
   		$\forall c>0,~F(x,cy)=cF(x,y),$
   		\item [(iii)] the Hessian matrix $(g_{ij}(x,y))_{1\leq i,j\leq n}$ with elements
   		\begin{eqnarray}\label{1}
   		g_{ij}(x,y):=\frac{1}{2}\frac{\partial^2F^2(x,y)}{\partial y^i\partial y^j}
   		\end{eqnarray}
   		is positive-definite at every point $(x,y)$ of $\mathring{T}M$.
   	\end{itemize}

The Hessian matrix $g$ whose elements are defined in (\ref{defi1}) is a natural Riemannian metric on the pulled-back bundle $\pi^*TM$ over the manifold 
	$\mathring{T}M$. $\pi^*TM$ is a vector bundle and its fiber at a point $(x,y)\in\mathring{T}M$ is
\begin{eqnarray}\label{12}
 \pi^*TM |_{(x,y)}:=\{(x,y;v): v\in T_xM\}|_{(x,y)}\cong T_xM.
\end{eqnarray}

\label{defi2} Let $\pi:\mathring{T}M\longrightarrow M$ be the 
	restricted projection.
	\begin{itemize}
		\item [(1)]A non-linear connection of $\pi$
		is the subbundle $\mathcal{H}$ of $T\mathring{T}M$ given by 
		\begin{eqnarray}
		\mathcal{H}:=ker \theta,
		\end{eqnarray}
		where $\theta:T\mathring{T}M\longrightarrow \pi^*TM$ is the bundle morphism defined 
		by 
		\begin{eqnarray}
		\label{03b}
		\theta|_{(x,y)}=\frac{\partial}{\partial x^i}\otimes \frac{1}{F}(dy^i+N_j^idx^j)
		\end{eqnarray}
		with $N_j^i(x,y):=\frac{\partial G^i(x,y)}{\partial y^j}$ 
		for 
		\begin{eqnarray}\label{Gcoef}
		G^i(x,y):=\frac{1}{4}g^{il}(x,y)
		\Big[\frac{\partial g_{jl}}{\partial x^k}(x,y)+\frac{\partial g_{kl}}{\partial x^j}(x,y)-\frac{\partial g_{jk}}{\partial x^l}(x,y)\Big]y^jy^k.
		\end{eqnarray}
		\item [(2)]The form $\theta:T\mathring{T}M\longrightarrow \pi^*TM$ induces a linear map 
		\begin{eqnarray}
		\theta|_{(x,y)}:T_{(x,y)}\mathring{T}M\longrightarrow T_xM,
		\end{eqnarray} 
		for each point $(x,y)\in \mathring{T}M$; where $x=\pi(x,y)$. \\
		The vertical lift of a section $\xi$ of $\pi^*TM$ is a unique section $\textbf{v}(\xi)$ of $T\mathring{T}M$ 
		such that for every $(x,y)\in \mathring{T}M$, 
		\begin{eqnarray}
		\pi_* (\textbf{v}(\xi))|_{(x,y)}=0_{(x,y)}\text{     and     }\theta (\textbf{v}(\xi))|_{(x,y)}=\xi_{(x,y)}.
		\end{eqnarray}
		\item [(3)]The differential projection $\pi_*:T\mathring{T}M\longrightarrow \pi^*TM$ induces a linear map 
		\begin{eqnarray}
		\pi_*|_{(x,y)}:T_{(x,y)}\mathring{T}M\longrightarrow T_xM,
		\end{eqnarray} 
		for each point $(x,y)\in \mathring{T}M$; where $x=\pi(x,y)$. \\
		The horizontal lift of a section $\xi$ of $\pi^*TM$ is a unique section $\textbf{h}(\xi)$ of $T\mathring{T}M$ 
		such that for every $(x,y)\in \mathring{T}M$,
		\begin{eqnarray}
		\pi_* (\textbf{h}(\xi))|_{(x,y)}=\xi_{(x,y)}\text{     and     }\theta (\textbf{h}(\xi))|_{(x,y)}=0_{(x,y)}.
		\end{eqnarray}
	\end{itemize}

\label{defi3b} 
	A Finslerian tensor field $T$ of type $(q,0;p_1,p_2)$
	on $\mathring{T}M$ is a $C^{\infty}$ section of the tensor bundle 
	\begin{eqnarray}
	\underbrace{\pi^*T^*M\otimes...\otimes\pi^*T^*M}_{p_1-times}
	\otimes \underbrace{T^*\mathring{T}M\otimes...\otimes T^*\mathring{T}M}_{p_2-times}
	\otimes\bigotimes^q\pi^*TM.  
	\end{eqnarray}

\label{rm2}
	In a local chart, $$T=T_{i_1...i_{p_1}j_1...j_{p_2}}^{k_1...k_q}\partial_{k_1}\otimes ... \otimes\partial_{k_q}
	\otimes dx^{i_1}\otimes...\otimes dx^{i_{p_1}}\otimes \varepsilon^{j_{1}}\otimes ... \otimes\varepsilon^{j_{p_2}}$$
	where $(\partial_{k_1}\otimes ... \otimes\partial_{k_q}
	\otimes dx^{i_1}\otimes...\otimes dx^{i_{p_1}}\otimes \varepsilon^{j_{1}}\otimes ... \otimes\varepsilon^{j_{p_2}})
	_{k\in\{1,...,n\}^q, i\in\{1,...,n\}^{p_1}, j\in\{1,...,n\}^{p_2}}$ is a basis section of this tensor 
	and, the $\partial_{k_r}:=\frac{\partial}{\partial x^{k_r}}$ as well as $\varepsilon^{j_{s}}$
	are respectively the basis sections for $\pi^*TM$ and $T^*\mathring{T}M$ dual of $T\mathring{T}M$.

\begin{itemize}
		\item [(1)]The Hessian matrix $g$, defined in (\ref{1}),  is of type $(0,0;2,0)$.
		\item [(2)] The Ehresmann-Finsler form $\theta$ is of type $(1,0;0,1)$.
	\end{itemize}

Let $F$ be a Finslerian metric, $\textbf{R}$ the first curvature associated with $F$ and $\{e_a\}_{a=1,...,n}$ an $g$-orthonormal basis sections of $\pi^*TM$. 
  \begin{itemize}
   \item [(1)] The first Ricci curvature $\hat{\textbf{r}}$ of $(M,F)$ is defined by 
   \begin{eqnarray}
    \hat{\textbf{r}}(\xi,X):=trace_g(\eta\longmapsto \textbf{R}(X,\textbf{h}(\eta)\xi), ~~\forall X\in\Gamma(T\mathring{T}M)~~and~~\xi,\eta\in\Gamma(\pi^*TM).
   \end{eqnarray}
In $g$-orthonormal basis sections $\{e_a\}_{a=1,...,n}$ of $\pi^*TM$, one has 
\begin{eqnarray}
    \hat{\textbf{r}}(\xi,X):=\sum_{a=1}^n\textbf{R}(e_a,\xi,X,\textbf{h}(e_a)).
   \end{eqnarray}
   \item [(2)] The first  scalar curvature $\hat{\textbf{S}}$ associated with $F$ is the trace of the first  Ricci curvature. 
   $\hat{\textbf{S}}$ is a function on $\mathring{T}M$ or on $SM$. In $g$-orthonormal basis sections $\{e_a\}_{a=1,...,n}$ of $\pi^*TM$, one has 
\begin{eqnarray}
    \hat{\textbf{S}}:=\sum_{a=1}^n\hat{\textbf{r}}(e_a,\textbf{h}(e_a))=\sum_{a,b=1}^n\textbf{R}(e_a,e_b,\textbf{h}(e_b),\textbf{h}(e_a)).
   \end{eqnarray}
  \end{itemize}

\label{0012}
  From the fact that all objects involved are of constant horizontal direction, we can see $u\in C^\infty(M)$
   as $u\in C^\infty(SM)$ of constant direction $[y]$.

\label{defi2}
	Let $(M,F)$ be an $n$-dimensional Finslerian manifold and $g$ the Hessian matrix associated with $F$.
	The gradient of a smooth function $u$ on $M$ is, the section of the vector bundle $\pi^*TM$ denoted by  $\triangledown u$, 
	 given by
	 \begin{eqnarray}
	 	g_{(x,y)}(\triangledown u_{(x,y)},\xi_{(x,y)})=du_{(x,y)}(\xi_{(x,y)})
	 \end{eqnarray}
	 for any $\xi\in\Gamma(\pi^*TM)$ and for every $(x,y)\in \mathring{T}M$. Locally, 
	 \begin{eqnarray}
	 \triangledown u_{(x,y)}=g^{ij}(x,y)\frac{\partial u}{\partial x^i}\frac{\partial }{\partial x^j}.
	 \end{eqnarray}

In the basis sections $\{\frac{\partial}{\partial x^i}\}_{i=1,...,n}$ of the pulled-back tangent bundle $\pi^*TM$, one get 
\begin{eqnarray}
\hat{D}\xi=g^{ij}g\left(\nabla_{\frac{\delta}{\delta x^i}}\xi,\frac{\partial}{\partial x^j}\right).
\end{eqnarray}

Suppose $u\in C^{\infty}(M)$. A Hessian of $u$ is the mapping
  \begin{eqnarray}
   Hu:\Gamma(\pi^*TM)\times \Gamma(T\mathring{T}M)\longrightarrow C^{\infty}(\mathring{T}M): 
   Hu(\xi,X)=g\left(\xi, \nabla_X(\triangledown u)\right).
  \end{eqnarray}

Let $(M,F)$ be a $C^{\infty}$ Finsler manifold and $u$ a $C^{\infty}$ function on $M$.



The horizontal Laplacian 
$\hat{\Delta}u$ of $u$ is given by 
\begin{eqnarray}\label{lp}
\hat{\Delta}u=-\hat{D}\triangledown u
\end{eqnarray}
and                                                 
the vertical Laplacian $\check{\Delta}u$ of $u$ by 
\begin{eqnarray}
 \check{\Delta}u=-\check{D}\triangledown u.
\end{eqnarray}

\cite{bi5}
   Let $u\in C^{\infty}(M)$. The horizontal Laplacian $\hat{\Delta}u$ and the vertical Laplacian $\check{\Delta}u$ of
   $u$ can be given in term of the Hessian of $u$ by
    \begin{eqnarray}
    \label{0}
    \hat{\Delta} u=-trace_g\left((\xi,\eta)\mapsto Hu(\xi,\textbf{h}(\eta))\right),~~~~  \xi,\eta\in\Gamma(\pi^*TM),
    \end{eqnarray}
    and 
    \begin{eqnarray}
    \check{\Delta} u=-trace_g\left((\xi,\eta)\mapsto Hu(\xi,\textbf{v}(\eta))\right),~~~~  \xi,\eta\in\Gamma(\pi^*TM).
    \end{eqnarray}
   Furthermore, in $g-$orthonormale basis sections $\{e_a\}_{a=1,...,n},$  one has
    \begin{eqnarray}
    \label{000}
     \hat{\Delta} u=-\sum_{a=1}^nHu(e_a,\textbf{h}(e_a))=-\hat{\nabla}^a\hat{\nabla}_au.
    \end{eqnarray}
    and 
    \begin{eqnarray}
     \check{\Delta} u=-\sum_{a=1}^nHu(e_a,\textbf{v}(e_a)).
    \end{eqnarray}

According to \cite{bi11}, we have the equation
 \begin{eqnarray}
\label{2}
 \frac{4(N-1)}{N-3}\hat{\Delta}\varphi-\hat{\textbf{S}}\varphi=-\hat{\widetilde{\textbf{S}}}\varphi^{\frac{N+5}{N-3}}
\end{eqnarray}
when $N=2n-1$ is the dimension of the Riemannian manifold $SM$.

\label{tp}
        Let $(M^3,F)$ be a 3-dimensional closed Finsler manifold and $\hat{\textbf{S}}$ his constant nonpositive horizontal scalar curvature. 
        Let $\widetilde{a_i}, i=0,1,2$ be the heat invariants for the sphere bundle $SM$ of $M$.
        Suppose $\alpha_0,\alpha_1,\alpha_2$ and $\Lambda$ are positives constants, and $\lambda_1(\widetilde F)$ is 
        the first positive eigenvalue of the horizontal Laplacian $\hat{\Delta}$. If $\widetilde{F}=\varphi^2F$
        ($\varphi\in C^2(M), \varphi\neq0, \varphi\neq1$) is a 
        Finsler metric on $M$ satisfying
        \begin{itemize}
         \item[(i)] $\widetilde{a}_0=\alpha_0,$
         \item[(ii)] $\widetilde{a}_1 \leq \alpha_1,$
         \item[(iii)] $\widetilde{a}_2 \leq \alpha_2$
         \item[(iv)] $0<\Lambda \leq \lambda_1(\widetilde F),$
        \end{itemize}
        then there exist constants $c_1, c_2$ and $c_3$ 
        (depending only on $\alpha_0,\alpha_1,\alpha_2$ and $\Lambda$) such that 
        \begin{itemize}
         \item[(v)] $0 < c_1 \leq \varphi((x,[y]))\leq c_2~~~\forall~(x,[y])\in SM,$
         \item[(vi)]

        $  ||\varphi||_{W^{2,2}(SM)} \leq c_3,$

  where
           \begin{eqnarray}
           \label{1000}
           ||\varphi||_{W^{2,2}(SM)}
         =\left(\int_{SM}|\varphi|^2\eta_F+\int_{SM}|\hat{\nabla}\varphi|^2\eta_F
         +\int_{SM}|\hat{\nabla}^2\varphi|^2\eta_F
         \right)^{\frac{1}{2}}.
         \end{eqnarray} 
        \end{itemize}

From the heat invariant $\widetilde{a_2}$, we have $\int_{SM}(\hat{\widetilde{\textbf{S}}})^2\eta_{\widetilde{F}}\leq 120\widetilde{a_2}$. But
 \begin{eqnarray}
  \int_{SM}(\hat{\widetilde{\textbf{S}}})^2\eta_{\widetilde{F}}&=&\int_{SM}|\hat{\textbf{S}}\varphi-c(N)\hat{\Delta}\varphi|^2\varphi^{\frac{-2(N+5)}{N-3}}
                                        \varphi^{\frac{2(N+1)}{N-3}}\eta_F\nonumber\\




       &=&\int_{SM}(\hat{\textbf{S}})^2\varphi^{-2}\eta_F-16\int_{SM}\hat{\textbf{S}}\varphi^{-3}(\hat{\Delta}\varphi)\eta_F
      +64\int_{SM}(\hat{\Delta}\varphi)^2\varphi^{-4}\eta_F.
 \end{eqnarray}
Using that $\hat{\textbf{S}}$ is constant and by integration by parts, we can rewrite the middle term as 
 \begin{eqnarray}
  I_2&=&-16\int_{SM}\hat{\textbf{S}}\varphi^{-3}(\hat{\Delta}\varphi)\eta_F\nonumber\\

     &=&-48 \hat{\textbf{S}}\int_{SM}|\hat{\nabla}\varphi|^2\varphi^{-4}\eta_F.
 \end{eqnarray}
 When $\hat{\textbf{S}}=0$ then $I_2=0$ and when $\hat{\textbf{S}}<0$ then $I_2> 0$.
  We have 
  \begin{eqnarray}
  \int_{SM}(\hat{\textbf{S}})^2\varphi^{-2}\eta_F+64\int_{SM}(\hat{\Delta}\varphi)^2\varphi^{-4}\eta_F 
  \leq\int_{SM}(\hat{\widetilde{\textbf{S}}})^2\eta_{\widetilde{F}}\leq 120\widetilde{a_2}.
  \end{eqnarray}
  So $\int_{SM}(\hat{\widetilde{\textbf{S}}})^2\eta_{\widetilde F}$ and hence

 $ \int_{SM}\varphi^{-4}(\hat{\Delta}\varphi)^2\eta_F$ and $\int_{SM}(\hat{\textbf{S}})^2\varphi^{-2}\eta_F$

   are apriori bounded, as desired.

Let $\overline{(\frac{1}{\varphi})}=\frac{1}{vol(SM)}\int_{SM}\frac{1}{\varphi}\eta_F$ be the average value of 
 $\frac{1}{\varphi}$. Then when dimension $M=3$ and $\hat{\textbf{S}}<0$ we have 
  \begin{eqnarray}
 \overline{\left(\frac{1}{\varphi}\right)}\leq c\left(\int_{SM}\frac{1}{\varphi^2}\eta_F\right)^{\frac{1}{2}}
   \end{eqnarray}
   by Cauchy-Schwartz, so that 
 $\overline{(\frac{1}{\varphi})}$ is apriori bounded, by the last peceding Lemma.\\

 We now compute, for any point $(x,[y])\in SM$, 
\begin{eqnarray}
\frac{1}{\varphi((x,[y]))}=\overline{\left(\frac{1}{\varphi}\right)}+\int_{SM}G\left((x,[y]),(z,[y])\right)
 \left[-\hat{\Delta}\left(\frac{1}{\varphi((z,[y]))}\right)\right]\eta_F((z,[y])) 
\end{eqnarray}
 where $G\left((x,[y]),(z,[y])\right)$ is the Green's function of the horizontal Laplacian $\hat{\Delta}$ on $SM$. Since
 \begin{eqnarray}
  \hat{\Delta}\left(\frac{1}{\varphi}\right)&=&-\frac{1}{\varphi^2}\hat{\Delta}\varphi+\frac{2|\hat{\nabla}\varphi|^2}{\varphi^3}\nonumber\\
                       &=&-\frac{1}{8\varphi^2}\left(\hat{\textbf{S}}\varphi-\hat{\widetilde{\textbf{S}}}\varphi^5\right)
                       +\frac{2|\hat{\nabla}\varphi|^2}{\varphi^3}
 \end{eqnarray}
by Yamabe equation. We get from Green's fonction that for any point $(x,[y])\in SM$,
\begin{eqnarray}
 \frac{1}{\varphi((x,[y]))}-\overline{\left(\frac{1}{\varphi}\right)}
 &=&\int_{SM}G((x,[y]),(z,[y])) \nonumber\\
 & &\times\left[\frac{1}{8}\hat{\textbf{S}}(\varphi)^{-1}
  -\frac{1}{8}\hat{\widetilde{\textbf{S}}}\varphi^3
  -\frac{2|\hat{\nabla}\varphi|^2}{\varphi^3}\right]\eta_F((z,[y]))\nonumber\\


  &\leq &\frac{1}{8}\left(\int_{SM}(G((x,[y]),(z,[y])))^2\eta_F((z,[y]))\right)^\frac{1}{2}\nonumber\\
 & & \times\left[\left(\int_{SM}(\hat{\textbf{S}})^2\varphi^{-2}\eta_F((z,[y]))\right)^\frac{1}{2}\right.\nonumber\\
 & & +\left.\left(\int_{SM}(\hat{\widetilde{\textbf{S}}})^2\varphi^6\eta_F((z,[y]))\right)^{\frac{1}{2}}\right],
\end{eqnarray}
where the two terms in the bracket are bounded by Lemma $5.2$, and nothing that, for dimension of $M=3$, $G((x,[y]),(z,[y]))$ is
square integrable. 
It follows that there exists a constant $c_1>0$ which does not depend on 
such that for any $(x,[y])\in SM$ $$0<c_1\leq \varphi((x,[y])).$$

Let $(M^3,F)$ be a 3-dimensional closed Finsler manifold and $SM$ its sphere bundle. Assume $\varphi$ be a positive function 
 on $SM$ which satisfies the hypothesis of theorem $5.1$, 
 there exists some $\varepsilon_0 > 0$ sufficiently small and a constant $c(a_0, a_1, a_2, \lambda_1)$ so that 
\begin{eqnarray}
 \int_{SM}\varphi^{6+\varepsilon_0}\eta_F\leq c.
 \end{eqnarray}

Let $\phi=\varphi^{1+\varepsilon}$ with $\varepsilon$ to be determine later. We have, from Sobolev inequality for $\phi$ \cite{bi11}, that 
 \begin{eqnarray}
 \label{98}
\left(\int_{SM}\phi^6\eta_F\right)^{\frac{1}{3}}\leq C_1\int_{SM}|\hat{\nabla}\phi|^2\eta_F+C_2\int_{SM}\phi^2\eta_F,
 \end{eqnarray}
where $C_1, C_2$ depend only on the geometry of $SM$.
On the other hand, multiplying the Yamabe (type) equation $8\hat{\Delta}\varphi-\hat{\textbf{S}}\varphi=-\hat{\widetilde{\textbf{S}}}\varphi^5$ by 
$\varphi^{1+2\varepsilon}$, we have 
\begin{eqnarray}
\label{99}
 8\varphi^{1+2\varepsilon}.\hat{\Delta}\varphi-\hat{\textbf{S}}\varphi^{2+2\varepsilon}=-\hat{\widetilde{\textbf{S}}}\varphi^4.\varphi^{2+2\varepsilon}.
\end{eqnarray}
By integration of (\ref{99}) and by using integration by parts, we get
\begin{eqnarray}
\label{100}
 8\int_{SM}\varphi^{1+2\varepsilon}.\hat{\Delta}\varphi\eta_F &=& 8\int_{SM}\hat{\Delta}\left(\phi^{\frac{1}{1+\varepsilon}}\right)
       \phi^{\frac{1+2\varepsilon}{1+\varepsilon}}\eta_F\nonumber\\


   &=& -\frac{8(1+2\varepsilon)}{(1+\varepsilon)^2}\int_{SM}\left|\hat{\nabla}\phi\right|^2\eta_F.\
\end{eqnarray}

so that
\begin{eqnarray}
 \label{101}
 & & \frac{8(1+2\varepsilon)}{(1+\varepsilon)^2}\int_{SM}\left|\hat{\nabla}\phi\right|^2\eta_F+\hat{\textbf{S}}\int_{SM}\phi^2\eta_F
 =\int_{SM}\hat{\widetilde{\textbf{S}}}\varphi^4\phi^2\eta_F\nonumber\\
 \end{eqnarray}
 or equivalently,
\begin{eqnarray}
  \int_{SM}\left|\hat{\nabla}\phi\right|^2\eta_F = \frac{(1+\varepsilon)^2}{8(1+2\varepsilon)}
 \int_{SM}\hat{\widetilde{\textbf{S}}}\varphi^4\phi^2\eta_F-\frac{(1+\varepsilon)^2}{8(1+2\varepsilon)}\hat{\textbf{S}}\int_{SM}\phi^2\eta_F.\nonumber\\
\end{eqnarray}
(\ref{101}) in (\ref{98}) 
\begin{eqnarray}
\label{102}
 \left(\int_{SM}\phi^6\eta_F\right)^{\frac{1}{3}}&\leq& C_1\left[\frac{(1+\varepsilon)^2}{8(1+2\varepsilon)}
 \int_{SM}\hat{\widetilde{\textbf{S}}}\varphi^4\phi^2\eta_F-\frac{(1+\varepsilon)^2}{8(1+2\varepsilon)}\hat{\textbf{S}}\int_{SM}\phi^2\eta_F\right]\nonumber\\
 & &+C_2\int_{SM}\phi^2\eta_F.
\end{eqnarray}
For $\varepsilon < 2$, $\int_{SM}\phi^2\eta_F$ is bounded by                                                           
some constant depending on $\varepsilon, \widetilde{a_0}$ and the volume of $SM$. Hence 
\begin{eqnarray}
 \left(\int_{SM}\phi^6\eta_F\right)^{\frac{1}{3}}&\leq& 
 C_1\frac{(1+\varepsilon)^2}{8(1+2\varepsilon)}\int_{SM}\hat{\widetilde{\textbf{S}}}\varphi^4\phi^2\eta_F+C_2(\varepsilon).\
\end{eqnarray}

We now seek to bound $\int_{SM}\hat{\widetilde{\textbf{S}}}\varphi^4\phi^2\eta_F$ from above in terms of $\int_{SM}\phi^6\eta_F$, and to 
that end we consider a large constant $b$ to be chosen later, and we consider the sets where $|\hat{\widetilde{\textbf{S}}}|\geq 0$ and 
$|\hat{\widetilde{\textbf{S}}}|<0$.\\
For $|\hat{\widetilde{\textbf{S}}}|\geq 0$,
\begin{eqnarray}
 \int_{|\hat{\widetilde{\textbf{S}}}|\geq b}\hat{\widetilde{\textbf{S}}}\varphi^4\phi^2\eta_F &\leq& \left(
 \int_{|\hat{\widetilde{\textbf{S}}}|\geq b}(\hat{\widetilde{\textbf{S}}})^2\varphi^6\eta_F\right)^{\frac{1}{2}}\left(
 \int_{|\hat{\widetilde{\textbf{S}}}|\geq b}\varphi^6\eta_F\right)^{\frac{1}{6}}\left(
 \int_{|\hat{\widetilde{\textbf{S}}}|\geq b}\phi^6\eta_F\right)^{\frac{1}{3}}\nonumber\\
 &\leq &\left(a_2\right)^{\frac{1}{2}}\left(\frac{a_2}{b^22}\right)^{\frac{1}{6}}
 \left(\int_{SM}\phi^6\eta_F\right)^{\frac{1}{3}},\
\end{eqnarray}
while for $|\hat{\widetilde{\textbf{S}}}|<b$ we have 
\begin{eqnarray}
 \int_{|\hat{\widetilde{\textbf{S}}}|<b}\hat{\widetilde{\textbf{S}}}\varphi^4\phi^2\eta_F &\leq& b\int_{SM}\varphi^4\phi^2\eta_F,
\end{eqnarray}
so that 
\begin{eqnarray}
\label{165}
 \int_{SM}\hat{\widetilde{\textbf{S}}}\varphi^4\phi^2\eta_F &\leq&\left(a_2\right)^{\frac{1}{2}}\left(\frac{a_2}{b_2}\right)^{\frac{1}{6}}
 \left(\int_{SM}\phi^6\eta_F\right)^{\frac{1}{3}}+b\int_{SM}\varphi^4\phi^2\eta_F.\
\end{eqnarray}
Let $\lambda_1=\lambda_1(\hat{\widetilde{\Delta}})\equiv \Lambda$ denote 
the first eigenvalue of $\hat{\Delta}$ acting on functions, then to estimate
 $\int_{SM}\varphi^4\phi^2\eta_F$, we apply the Rayleigh-Ritz characterization of $\lambda_1$ \cite{}:
 \begin{eqnarray}
  \lambda_1(\hat{\widetilde{\Delta}})\leq \frac{\int_{SM}|\hat{\nabla}_{\widetilde F}\psi|^2\eta_{\widetilde F}}
  {\int_{SM}\psi^2\eta_{\widetilde F}-(vol(SM))^{-1}\left(\int_{SM}\psi\eta_{\widetilde F}\right)^2}
 \end{eqnarray}
or equivalently, 
\begin{eqnarray}
 \int_{SM}\psi^2\eta_{\widetilde F}\leq (vol(SM))^{-1}\left(\int_{SM}\psi\eta_{\widetilde F}\right)^2
 +\frac{1}{\lambda_1}\int_{SM}|\hat{\nabla}_{\widetilde F}\psi|^2\eta_{\widetilde F}
\end{eqnarray}
to $\psi=\varphi^{\varepsilon}$ to obtain
\begin{eqnarray}
 \int_{SM}\varphi^4\phi^2\eta_F\leq \left(\int_{SM}\varphi^6\eta_F\right)^{-1}
 \left(\int_{SM}\varphi^{6+\varepsilon}\eta_F\right)^{2}+
 \frac{1}{\lambda_1}\int_{SM}|\hat{\nabla}\varphi^{\varepsilon}|^2\eta_{\widetilde F}.
\end{eqnarray}
But 
\begin{eqnarray}
 \int_{SM}|\hat{\nabla}_{\widetilde F}\varphi^\varepsilon|^2\eta_{\widetilde F}&=&
 \int_{SM}|\hat{\nabla}\varphi^\varepsilon|^2\varphi^2\eta_F\nonumber\\

 &=&\frac{\varepsilon^2}{8(1+\varepsilon)}\left(\int_{SM}\hat{\widetilde{\textbf{S}}}\varphi^4\phi^2\eta_F-
 \hat{\textbf{S}}\int_{SM}\phi^2\eta_F\right)\nonumber\\
\end{eqnarray}
where again we have used $8\hat{\Delta}\varphi-\hat{\textbf{S}}\varphi=-\hat{\widetilde{\textbf{S}}}\varphi^5$ to obtain the last line.\\
To estimate $\int_{SM}\varphi^{6+\varepsilon}\eta_F$, we choose $c$ as in Lemma $5.4$, with $\varphi-c\geq 0$, so that
\begin{eqnarray}
 \int_{SM}\varphi^{6+\varepsilon}\eta_F &=& \int_{SM}(\varphi^6-c^6)\varphi^\varepsilon\eta_F
                                  +\int_{SM}c^6\varphi^\varepsilon\eta_F \nonumber\\
 &\leq& \left[\int_{SM}(\varphi^6-c^6)\varphi^{2\varepsilon}\eta_F\right]^{\frac{1}{2}}
 \left[(\varphi^6-c^6)\eta_F\right]^{\frac{1}{2}}+\int_{SM}c^6\varphi^\varepsilon\eta_F,
\end{eqnarray}
where the inequality comes from Cauchy-Schwartz and the positivity of $(\varphi^6-c^6)$. 
Squaring and using the inequality $2AB\leq\delta A^2+(\frac{1}{\delta})B^2$, we obtain
\begin{eqnarray}
\left(\int_{SM}\varphi^{6+\varepsilon}\right)^{\frac{1}{2}}\leq (1+\delta)\left[
\int_{SM}(\varphi^6-c^6)\varphi^{2\varepsilon}\eta_F\right]\left[(\varphi^6-c^6)\eta_F\right]
+(1+\delta)\left[\int_{SM}c^6\varphi^\varepsilon\eta_F\right]
\end{eqnarray}
where $\delta$ will be chosen late. But $\int_{SM}(\varphi^6-c^6)\eta_F=\alpha.\int_{SM}\varphi^6\eta_F$ 
where $\alpha =1-\frac{c^6.vol_{F}(SM)}{vol_{\widetilde{F}}(SM)}$ is a positive constant less than 1 and we conclude 
\begin{eqnarray}
 \left(\int_{SM}\varphi^6\eta_F\right)^{-1}\left(\int_{SM}\varphi^{6+\varepsilon}\eta_F\right)^2
 &\leq& (1+\delta).\alpha\left(\int_{SM}\varphi^{6+2\varepsilon}\eta_F\right)+(1+\frac{1}{\delta}).(constant).
\end{eqnarray}
Choosing $\delta$ so that $(1+\delta)\alpha=(1-\nu) < 1$, we then have 
\begin{eqnarray}
\int_{SM}\varphi^4\phi^2\eta_F\leq(1-\nu)\int_{SM}\varphi^4\phi^2\eta_F+\frac{\varepsilon^2}{8(1+\varepsilon)}
\int_{SM}\hat{\widetilde{\textbf{S}}}\varphi^4\phi^2\eta_F+(constant),
\end{eqnarray}
so that
\begin{eqnarray}
\label{200}
 \int_{SM}\varphi^4\phi^2\eta_F\leq\frac{1}{\nu}\left[\frac{\varepsilon^2}{8(1+\varepsilon)}
\int_{SM}\hat{\widetilde{\textbf{S}}}\varphi^4\phi^2\eta_F+(constant)\right].
\end{eqnarray}
Combining (\ref{165}) and (\ref{200}), we see that 
\begin{eqnarray}
 \int_{SM}\hat{\widetilde{\textbf{S}}}\varphi^4\phi^2\eta_F\leq (a_2)^{\frac{1}{2}}\left(\frac{a_2}{b_2}\right)^{\frac{1}{6}}
 \left(\int_{SM}\phi^6\eta_F\right)^{\frac{1}{3}}+\frac{b}{\nu}\left[\frac{\varepsilon^2}{8(1+\varepsilon)}
\int_{SM}\hat{\widetilde{\textbf{S}}}\varphi^4\phi^2\eta_F+(constant)\right].
\end{eqnarray}
Choosing $b$ large so that the coefficient of $\left(\int_{SM}\phi^6\eta_F\right)^{\frac{1}{3}}$ is $<\varphi_1$ 
and then choosing $\varepsilon$ small so that the coefficient of $\int_{SM}\hat{\widetilde{\textbf{S}}}\varphi^4\phi^2\eta_F$ 
is $<\varphi_2$, we have
\begin{eqnarray}
 (1-\varphi_2)\int_{SM}\hat{\widetilde{\textbf{S}}}\varphi^4\phi^2\eta_F\leq
 \varphi_1\left(\int_{SM}\phi^6\eta_F\right)^{\frac{1}{3}}+(constant),
\end{eqnarray}
and comparing with the lower bound (\ref{102}), we have an upper bound for $\left(\int_{SM}\phi^6\eta_F\right)^{\frac{1}{3}}$
 as soon as $\frac{8(1+2\varepsilon)}{C_1(1+\varepsilon)^2}\geq\frac{\varphi_1}{1-\varphi_2}$,
 which achieved by taking $\varepsilon$ sufficiently small. This proves Lemma 4.
